:[{"Ar":"لكل قميص خياران من السراويل، وجميع الملابس مختلفة.","En":"Each shirt has two trouser choices, and all garments are distinct."},{"Ar":"$3\\cdot2$","En":"$3\\cdot2$"},{"Ar":"نعد مجموعتين لكل قميص من القمصان الثلاثة باستعمال الضرب.","En":"Count two outfits per shirt for three shirts using multiplication."}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"لا تجمع أعداد الخيارات عندما نختار واحداً من كل مجموعة.","En":"Do not add option counts when selecting one from each group."},"FormulaLatex":"N=n_s n_t","Substitution":{"Ar":"$6$","En":"$6$"},"Verification":{"Ar":"$2+2+2=6$","En":"$2+2+2=6$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"5 يجمع عدد الملابس ولا يعد الأزواج.","En":"Five adds garment counts rather than counting pairs."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يتجاوز عدد الأزواج الممكنة من ثلاثة في اثنين.","En":"Eight exceeds the possible three-by-two pairs."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"9 يفترض ثلاثة خيارات للسروال بدلاً من اثنين.","En":"Nine assumes three trouser choices instead of two."},"Order":4}]}$mw$,$mw$مبدأ العد الأساسي: نضرب عدد الخيارات المستقلة في كل خطوة.

